using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;
using Grpc.Core;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace SecureGrpcService
{
    public class ConnectionState
    {
        public string ClientId { get; set; }
        public string AuthToken { get; set; }
        public bool IsAuthenticated { get; set; }
        public DateTime LastActivity { get; set; }
        public int RequestCount { get; set; }
    }

    public class GrpcServiceHost : IHostedService
    {
        private readonly ILogger<GrpcServiceHost> _logger;
        private readonly ConcurrentDictionary<string, ConnectionState> _connections;
        private Server _server;
        private volatile int _shutdownPhase = 0; // 0=running, 1=draining, 2=stopped
        private readonly SemaphoreSlim _stateLock = new SemaphoreSlim(1, 1);
        private CancellationTokenSource _shutdownCts;
        private readonly object _phaseLock = new object();

        public GrpcServiceHost(ILogger<GrpcServiceHost> logger)
        {
            _logger = logger;
            _connections = new ConcurrentDictionary<string, ConnectionState>();
            _shutdownCts = new CancellationTokenSource();
        }

        public Task StartAsync(CancellationToken cancellationToken)
        {
            AppDomain.CurrentDomain.ProcessExit += OnProcessExit;
            Console.CancelKeyPress += OnCancelKeyPress;

            _server = new Server
            {
                Ports = { new ServerPort("0.0.0.0", 50051, ServerCredentials.Insecure) }
            };
            _server.Start();
            _logger.LogInformation("gRPC server started on port 50051");
            return Task.CompletedTask;
        }

        public async Task StopAsync(CancellationToken cancellationToken)
        {
            await InitiateGracefulShutdown();
        }

        private void OnProcessExit(object sender, EventArgs e)
        {
            _logger.LogWarning("SIGTERM received, initiating shutdown");
            InitiateGracefulShutdown().GetAwaiter().GetResult();
        }

        private void OnCancelKeyPress(object sender, ConsoleCancelEventArgs e)
        {
            e.Cancel = true;
            _logger.LogWarning("SIGINT received, initiating shutdown");
            _ = InitiateGracefulShutdown();
        }

        private async Task InitiateGracefulShutdown()
        {
            // Phase transition: running -> draining
            lock (_phaseLock)
            {
                if (_shutdownPhase >= 1) return;
                _shutdownPhase = 1;
            }

            _logger.LogInformation("Entering drain phase, notifying reverse proxy");
            await NotifyProxyDraining();

            // Drain existing connections with timeout
            var drainTimeout = Task.Delay(TimeSpan.FromSeconds(30));
            var drainComplete = DrainConnections();
            await Task.WhenAny(drainTimeout, drainComplete);

            // Phase transition: draining -> stopped
            lock (_phaseLock)
            {
                _shutdownPhase = 2;
            }

            _shutdownCts.Cancel();
            await (_server?.ShutdownAsync() ?? Task.CompletedTask);
            _logger.LogInformation("Server shutdown complete");
        }

        private async Task NotifyProxyDraining()
        {
            // Simulate notifying the reverse proxy (e.g., deregister from consul/envoy)
            await Task.Delay(100);
        }

        private async Task DrainConnections()
        {
            while (_connections.Count > 0)
            {
                await Task.Delay(500);
                foreach (var kvp in _connections)
                {
                    if ((DateTime.UtcNow - kvp.Value.LastActivity).TotalSeconds > 5)
                    {
                        _connections.TryRemove(kvp.Key, out _);
                    }
                }
            }
        }

        // Called by gRPC interceptor for each incoming request
        public async Task<bool> HandleIncomingRequest(string connectionId, string authHeader)
        {
            // Check if we're accepting requests
            if (_shutdownPhase >= 2)
            {
                return false; // Reject
            }

            var state = _connections.GetOrAdd(connectionId, id => new ConnectionState
            {
                ClientId = id,
                IsAuthenticated = false,
                LastActivity = DateTime.UtcNow,
                RequestCount = 0
            });

            // Race window: between checking _shutdownPhase and acquiring state lock,
            // the signal handler can transition to phase 2 and cancel the CTS.
            // The connection was added to _connections but authentication hasn't
            // completed yet. During drain, this half-initialized connection
            // may be served by a different handler that assumes IsAuthenticated
            // was properly set.

            await _stateLock.WaitAsync(_shutdownCts.Token);
            try
            {
                if (!state.IsAuthenticated)
                {
                    state.AuthToken = authHeader;
                    // Simulate async token validation against identity provider
                    var isValid = await ValidateTokenAsync(authHeader);
                    state.IsAuthenticated = isValid;
                }

                state.LastActivity = DateTime.UtcNow;
                state.RequestCount++;

                return state.IsAuthenticated;
            }
            catch (OperationCanceledException)
            {
                // Shutdown occurred during auth - connection is in _connections
                // but IsAuthenticated is still false. However, the connection
                // object exists and RequestCount may have been incremented.
                // We do NOT remove from _connections here, leaving a dangling entry.
                return false;
            }
            finally
            {
                _stateLock.Release();
            }
        }

        // Called by streaming RPCs that maintain long-lived connections
        public async Task<string> GetSessionData(string connectionId)
        {
            if (_connections.TryGetValue(connectionId, out var state))
            {
                // BUG: During the race between signal handler cancellation and
                // HandleIncomingRequest, state.IsAuthenticated may be false
                // but the connection exists. A concurrent streaming RPC
                // that was already past its own auth check can call this
                // method. The check below uses RequestCount > 0 as a proxy
                // for "has been processed" but the race means RequestCount
                // can be incremented before IsAuthenticated is set.
                if (state.RequestCount > 0)
                {
                    state.LastActivity = DateTime.UtcNow;
                    return $"session:{state.ClientId}:token:{state.AuthToken}";
                }
            }
            return null;
        }

        private async Task<bool> ValidateTokenAsync(string token)
        {
            // Simulate external validation
            await Task.Delay(50);
            return !string.IsNullOrEmpty(token) && token.StartsWith("Bearer ");
        }
    }
}
